from storage_client import AzureBlobStorageClient
from storage_models import UploadObjectRequest, UploadObjectResponse
from azure.core.exceptions import ResourceNotFoundError

def upload_object(request: UploadObjectRequest) -> UploadObjectResponse:
    client = AzureBlobStorageClient()
    try:
        blob_client = client.get_blob_client(request.container_name, request.blob_name)
        response = blob_client.upload_blob(request.data, overwrite=True, content_settings=request.content_settings)
        return UploadObjectResponse(
            success=True,
            blob_url=blob_client.url,
            e_tag=response['etag'],
            last_modified=str(response['last_modified'])
        )
    except ResourceNotFoundError:
        return UploadObjectResponse(success=False, error=f"Container '{request.container_name}' not found.")
    except Exception as e:
        return UploadObjectResponse(success=False, error=str(e))

from storage_client import AzureBlobStorageClient
from storage_models import PresignedDownloadRequest, PresignedDownloadResponse
from azure.core.exceptions import ResourceNotFoundError

def presigned_download(request: PresignedDownloadRequest) -> PresignedDownloadResponse:
    client = AzureBlobStorageClient()
    try:
        # Verify the blob exists before generating a SAS URL
        blob_client = client.get_blob_client(request.container_name, request.blob_name)
        blob_client.get_blob_properties() # This will raise ResourceNotFoundError if blob/container doesn't exist

        presigned_url = client.generate_sas_url(request.container_name, request.blob_name, request.expiry_minutes)
        return PresignedDownloadResponse(success=True, presigned_url=presigned_url)
    except ResourceNotFoundError:
        return PresignedDownloadResponse(success=False, error=f"Blob '{request.blob_name}' not found in container '{request.container_name}'.")
    except Exception as e:
        return PresignedDownloadResponse(success=False, error=str(e))

from storage_client import AzureBlobStorageClient
from storage_models import ObjectMetadataRequest, ObjectMetadataResponse
from azure.core.exceptions import ResourceNotFoundError

def object_metadata(request: ObjectMetadataRequest) -> ObjectMetadataResponse:
    client = AzureBlobStorageClient()
    try:
        blob_client = client.get_blob_client(request.container_name, request.blob_name)
        properties = blob_client.get_blob_properties()
        return ObjectMetadataResponse(
            success=True,
            name=properties.name,
            size=properties.size,
            creation_time=str(properties.creation_time),
            last_modified=str(properties.last_modified),
            e_tag=properties.etag,
            content_settings={
                "content_type": properties.content_settings.content_type,
                "content_encoding": properties.content_settings.content_encoding,
                "content_language": properties.content_settings.content_language,
                "content_disposition": properties.content_settings.content_disposition,
                "cache_control": properties.content_settings.cache_control,
                "content_md5": properties.content_settings.content_md5
            },
            metadata=properties.metadata
        )
    except ResourceNotFoundError:
        return ObjectMetadataResponse(success=False, error=f"Blob '{request.blob_name}' not found in container '{request.container_name}'.")
    except Exception as e:
        return ObjectMetadataResponse(success=False, error=str(e))

from storage_client import AzureBlobStorageClient
from storage_models import ListPrefixRequest, ListPrefixResponse
from azure.core.exceptions import ResourceNotFoundError

def list_prefix(request: ListPrefixRequest) -> ListPrefixResponse:
    client = AzureBlobStorageClient()
    try:
        container_client = client.blob_service_client.get_container_client(request.container_name)
        blob_names = []
        for blob in container_client.list_blobs(name_starts_with=request.prefix):
            blob_names.append(blob.name)
        return ListPrefixResponse(success=True, blob_names=blob_names)
    except ResourceNotFoundError:
        return ListPrefixResponse(success=False, error=f"Container '{request.container_name}' not found.")
    except Exception as e:
        return ListPrefixResponse(success=False, error=str(e))

import os
from azure.ai.vision.imageanalysis import ImageAnalysisClient
from azure.ai.vision.imageanalysis.models import VisualFeatures
from azure.core.credentials import AzureKeyCredential
from storage_client import AzureBlobStorageClient
from storage_models import StoredDocumentOcrRequest, StoredDocumentOcrResponse
from azure.core.exceptions import ResourceNotFoundError
from dotenv import load_dotenv

load_dotenv()

def stored_document_ocr(request: StoredDocumentOcrRequest) -> StoredDocumentOcrResponse:
    endpoint = os.getenv("AZURE_VISION_ENDPOINT")
    key = os.getenv("AZURE_VISION_KEY")

    if not endpoint or not key:
        return StoredDocumentOcrResponse(success=False, error="AZURE_VISION_ENDPOINT or AZURE_VISION_KEY environment variables not set.")

    vision_client = ImageAnalysisClient(endpoint=endpoint, credential=AzureKeyCredential(key))
    storage_client = AzureBlobStorageClient()

    try:
        blob_client = storage_client.get_blob_client(request.container_name, request.blob_name)
        # Get the URL of the blob for OCR processing
        blob_url = blob_client.url

        # Analyze the image for text content
        result = vision_client.analyze(url=blob_url, visual_features=[VisualFeatures.READ])

        if result.read and result.read.blocks:
            text_content = "\n".join([line.text for block in result.read.blocks for line in block.lines])
            return StoredDocumentOcrResponse(success=True, text_content=text_content)
        else:
            return StoredDocumentOcrResponse(success=True, text_content="No text found in the document.")

    except ResourceNotFoundError:
        return StoredDocumentOcrResponse(success=False, error=f"Blob '{request.blob_name}' not found in container '{request.container_name}'.")
    except Exception as e:
        return StoredDocumentOcrResponse(success=False, error=str(e))

import os
import requests
import uuid
from dotenv import load_dotenv
from storage_models import StoredTextTranslateRequest, StoredTextTranslateResponse

load_dotenv()

def stored_text_translate(request: StoredTextTranslateRequest) -> StoredTextTranslateResponse:
    key = os.getenv("AZURE_TRANSLATOR_KEY")
    endpoint = os.getenv("AZURE_TRANSLATOR_ENDPOINT")
    location = os.getenv("AZURE_TRANSLATOR_LOCATION")

    if not key or not endpoint or not location:
        return StoredTextTranslateResponse(success=False, error="Azure Translator environment variables (KEY, ENDPOINT, LOCATION) not set.")

    path = '/translate'
    constructed_url = endpoint + path

    params = {
        'api-version': '3.0',
        'to': request.target_language
    }
    if request.source_language:
        params['from'] = request.source_language

    headers = {
        'Ocp-Apim-Subscription-Key': key,
        'Ocp-Apim-Subscription-Region': location,
        'Content-type': 'application/json',
        'X-ClientTraceId': str(uuid.uuid4())
    }

    body = [{'text': request.text}]

    try:
        translator_response = requests.post(constructed_url, params=params, headers=headers, json=body)
        translator_response.raise_for_status() # Raise an exception for HTTP errors
        response_json = translator_response.json()

        if response_json and len(response_json) > 0 and 'translations' in response_json[0] and len(response_json[0]['translations']) > 0:
            translated_text = response_json[0]['translations'][0]['text']
            return StoredTextTranslateResponse(success=True, translated_text=translated_text)
        else:
            return StoredTextTranslateResponse(success=False, error="Translation failed: No translations found in the response.")

    except requests.exceptions.RequestException as e:
        return StoredTextTranslateResponse(success=False, error=f"Translation request failed: {e}")
    except Exception as e:
        return StoredTextTranslateResponse(success=False, error=str(e))

import os
from openai import AzureOpenAI
from storage_client import AzureBlobStorageClient
from storage_models import StoredAssetSummaryRequest, StoredAssetSummaryResponse
from azure.core.exceptions import ResourceNotFoundError
from dotenv import load_dotenv

load_dotenv()

def stored_asset_summary(request: StoredAssetSummaryRequest) -> StoredAssetSummaryResponse:
    azure_openai_endpoint = os.getenv("AZURE_OPENAI_ENDPOINT")
    azure_openai_key = os.getenv("AZURE_OPENAI_KEY")
    azure_openai_api_version = os.getenv("AZURE_OPENAI_API_VERSION", "2024-02-15-preview")
    azure_openai_deployment_name = os.getenv("AZURE_OPENAI_SUMMARIZE_DEPLOYMENT_NAME")

    if not azure_openai_endpoint or not azure_openai_key or not azure_openai_deployment_name:
        return StoredAssetSummaryResponse(success=False, error="Azure OpenAI environment variables (ENDPOINT, KEY, SUMMARIZE_DEPLOYMENT_NAME) not set.")

    client = AzureOpenAI(
        azure_endpoint = azure_openai_endpoint,
        api_key = azure_openai_key,
        api_version = azure_openai_api_version
    )

    storage_client = AzureBlobStorageClient()

    try:
        blob_client = storage_client.get_blob_client(request.container_name, request.blob_name)
        downloaded_blob = blob_client.download_blob()
        text_content = downloaded_blob.readall().decode('utf-8')

        if not text_content:
            return StoredAssetSummaryResponse(success=True, summary="No content to summarize.")

        prompt = f"Summarize the following text in {request.max_sentences} sentences:\n\n{text_content}"
        response = client.chat.completions.create(
            model=azure_openai_deployment_name,
            messages=[
                {"role": "system", "content": "You are a helpful assistant that summarizes text."},
                {"role": "user", "content": prompt}
            ],
            temperature=0.7,
            max_tokens=250 # Adjust as needed for summary length
        )

        summary = response.choices[0].message.content.strip()
        return StoredAssetSummaryResponse(success=True, summary=summary)

    except ResourceNotFoundError:
        return StoredAssetSummaryResponse(success=False, error=f"Blob '{request.blob_name}' not found in container '{request.container_name}'.")
    except Exception as e:
        return StoredAssetSummaryResponse(success=False, error=str(e))

import os
from openai import AzureOpenAI
from storage_client import AzureBlobStorageClient
from storage_models import AssetMetadataEmbeddingRequest, AssetMetadataEmbeddingResponse, ObjectMetadataRequest, ObjectMetadataResponse
from object_metadata import object_metadata
from azure.core.exceptions import ResourceNotFoundError
from dotenv import load_dotenv

load_dotenv()

def asset_metadata_embedding(request: AssetMetadataEmbeddingRequest) -> AssetMetadataEmbeddingResponse:
    azure_openai_endpoint = os.getenv("AZURE_OPENAI_ENDPOINT")
    azure_openai_key = os.getenv("AZURE_OPENAI_KEY")
    azure_openai_api_version = os.getenv("AZURE_OPENAI_API_VERSION", "2024-02-15-preview")
    azure_openai_embedding_deployment_name = os.getenv("AZURE_OPENAI_EMBEDDING_DEPLOYMENT_NAME")

    if not azure_openai_endpoint or not azure_openai_key or not azure_openai_embedding_deployment_name:
        return AssetMetadataEmbeddingResponse(success=False, error="Azure OpenAI environment variables (ENDPOINT, KEY, EMBEDDING_DEPLOYMENT_NAME) not set.")

    client = AzureOpenAI(
        azure_endpoint = azure_openai_endpoint,
        api_key = azure_openai_key,
        api_version = azure_openai_api_version
    )

    try:
        # Get object metadata
        metadata_request = ObjectMetadataRequest(container_name=request.container_name, blob_name=request.blob_name)
        metadata_response = object_metadata(metadata_request)

        if not metadata_response.success:
            return AssetMetadataEmbeddingResponse(success=False, error=f"Failed to retrieve metadata: {metadata_response.error}")

        # Combine relevant metadata and optionally provided text content for embedding
        text_to_embed = f"Blob Name: {metadata_response.name}. "
        if metadata_response.content_settings and metadata_response.content_settings.get("content_type"):
            text_to_embed += f"Content Type: {metadata_response.content_settings['content_type']}. "
        if metadata_response.metadata:
            for k, v in metadata_response.metadata.items():
                text_to_embed += f"{k}: {v}. "
        if request.text_content:
            text_to_embed += f"Document Content: {request.text_content}"

        if not text_to_embed.strip():
            return AssetMetadataEmbeddingResponse(success=False, error="No text content or metadata to embed.")

        response = client.embeddings.create(
            input=text_to_embed,
            model=azure_openai_embedding_deployment_name
        )

        embedding = response.data[0].embedding
        return AssetMetadataEmbeddingResponse(success=True, embedding=embedding)

    except ResourceNotFoundError:
        return AssetMetadataEmbeddingResponse(success=False, error=f"Blob '{request.blob_name}' not found in container '{request.container_name}'.")
    except Exception as e:
        return AssetMetadataEmbeddingResponse(success=False, error=str(e))
